import React, { useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { Box } from '@mui/material';
import { useDispatch } from 'react-redux';

// Components
import Navbar from './components/layout/Navbar';
import Footer from './components/layout/Footer';
import LoadingSpinner from './components/common/LoadingSpinner';
import ProtectedRoute from './components/common/ProtectedRoute';

// Context
import { CartProvider } from './context/CartContext';
import { AuthProvider } from './context/AuthContext';

// Pages
import HomePage from './pages/HomePage';
import ProductsPage from './pages/ProductsPage';
import ProductDetailPage from './pages/ProductDetailPage';
import CartPage from './pages/CartPage';
import CheckoutPage from './pages/CheckoutPage';
import OrdersPage from './pages/OrdersPage';
import OrderDetailPage from './pages/OrderDetailPage';
import ProfilePage from './pages/ProfilePage';
import LoginPage from './pages/LoginPage';
import SignupPage from './pages/SignupPage';

// Services
import { useSocket } from './hooks/useSocket';
import { useCart } from './hooks/useCart';

// Store actions
import { updateCartFromSocket } from './store/slices/cartSlice';
import { updateOrderFromSocket } from './store/slices/orderSlice';

function App() {
  const dispatch = useDispatch();
  const { socket, isConnected } = useSocket();
  const { sessionId } = useCart();

  // Set up socket event listeners
  useEffect(() => {
    if (!socket || !isConnected) return;

    console.log('🔌 Socket connected, setting up event listeners');

    // Join session room for real-time updates
    if (sessionId) {
      socket.emit('join-session', sessionId);
    }

    // Cart update listeners
    const handleCartUpdate = (data) => {
      console.log('🛒 Real-time cart update:', data);
      dispatch(updateCartFromSocket(data));
    };

    // Order update listeners
    const handleOrderUpdate = (data) => {
      console.log('📦 Real-time order update:', data);
      dispatch(updateOrderFromSocket(data));
    };

    // Stock update listeners (for product pages)
    const handleStockUpdate = (data) => {
      console.log('📦 Real-time stock update:', data);
      // Trigger product list refresh or update specific product
      window.dispatchEvent(new CustomEvent('stock-updated', { detail: data }));
    };

    // Set up event listeners
    socket.on('cart-updated', handleCartUpdate);
    socket.on('order-created', handleOrderUpdate);
    socket.on('order-updated', handleOrderUpdate);
    socket.on('stock-updated', handleStockUpdate);

    // Connection status listeners
    socket.on('connect', () => {
      console.log('✅ Socket connected');
    });

    socket.on('disconnect', () => {
      console.log('❌ Socket disconnected');
    });

    socket.on('reconnect', () => {
      console.log('🔄 Socket reconnected');
      if (sessionId) {
        socket.emit('join-session', sessionId);
      }
    });

    // Cleanup event listeners
    return () => {
      socket.off('cart-updated', handleCartUpdate);
      socket.off('order-created', handleOrderUpdate);
      socket.off('order-updated', handleOrderUpdate);
      socket.off('stock-updated', handleStockUpdate);
      socket.off('connect');
      socket.off('disconnect');
      socket.off('reconnect');
    };
  }, [socket, isConnected, sessionId, dispatch]);

  return (
    <AuthProvider>
      <CartProvider>
        <Router>
        <Box 
          sx={{ 
            display: 'flex', 
            flexDirection: 'column', 
            minHeight: '100vh' 
          }}
        >
        <Navbar />
        
        <Box 
          component="main" 
          sx={{ 
            flex: 1, 
            py: 3,
            backgroundColor: '#fafafa'
          }}
        >
          <Routes>
            <Route path="/" element={<HomePage />} />
            <Route path="/products" element={<ProductsPage />} />
            <Route path="/products/:id" element={<ProductDetailPage />} />
            <Route path="/cart" element={
              <ProtectedRoute>
                <CartPage />
              </ProtectedRoute>
            } />
            <Route path="/checkout" element={
              <ProtectedRoute>
                <CheckoutPage />
              </ProtectedRoute>
            } />
            <Route path="/orders" element={
              <ProtectedRoute>
                <OrdersPage />
              </ProtectedRoute>
            } />
            <Route path="/orders/:orderId" element={
              <ProtectedRoute>
                <OrderDetailPage />
              </ProtectedRoute>
            } />
            <Route path="/login" element={
              <ProtectedRoute requireAuth={false}>
                <LoginPage />
              </ProtectedRoute>
            } />
            <Route path="/signup" element={
              <ProtectedRoute requireAuth={false}>
                <SignupPage />
              </ProtectedRoute>
            } />
            
            {/* Fallback route */}
            <Route 
              path="*" 
              element={
                <Box 
                  display="flex" 
                  justifyContent="center" 
                  alignItems="center" 
                  minHeight="400px"
                >
                  <div>
                    <h2>404 - Page Not Found</h2>
                    <p>The page you're looking for doesn't exist.</p>
                  </div>
                </Box>
              } 
            />
          </Routes>
        </Box>

        <Footer />

        {/* Connection status indicator */}
        {!isConnected && (
          <Box
            position="fixed"
            bottom={16}
            left={16}
            bgcolor="warning.main"
            color="white"
            px={2}
            py={1}
            borderRadius={1}
            fontSize="0.875rem"
            zIndex={1000}
          >
            🔌 Reconnecting to server...
          </Box>
        )}
        </Box>
        </Router>
      </CartProvider>
    </AuthProvider>
  );
}

export default App;
